package android.content;import android.os.*;public class Intent{private final Bundle b=new Bundle();public final Class<?> target;public boolean failExtra;public Intent(){target=null;}public Intent(Context c,Class<?> t){target=t;}public Intent putExtra(String k,String v){if(failExtra)throw new IllegalStateException("fixture");b.putString(k,v);return this;}public Intent putExtra(String k,Parcelable v){if(failExtra)throw new IllegalStateException("fixture");b.putParcelable(k,v);return this;}public String getStringExtra(String k){return b.getString(k);}public Bundle getExtras(){return b;}}
